CREATE TABLE AB_BILL_SOURCE_DTL (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    TYPE_CODE VARCHAR2(10) NULL,
    BRIEF_ID VARCHAR2(10) NULL,
    SOURCE VARCHAR2(10) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE AB_BILL_SOURCE_DTL IS '票据业务来源明细';
COMMENT ON COLUMN AB_BILL_SOURCE_DTL.ID IS '表ID';
COMMENT ON COLUMN AB_BILL_SOURCE_DTL.TYPE_CODE IS '来源类型';
COMMENT ON COLUMN AB_BILL_SOURCE_DTL.BRIEF_ID IS '业务代码';
COMMENT ON COLUMN AB_BILL_SOURCE_DTL.SOURCE IS '来源代码';
COMMENT ON COLUMN AB_BILL_SOURCE_DTL.TENANT_ID IS '租户ID';

CREATE INDEX IDX_AB_BILL_SOURCE_DTL_T ON AB_BILL_SOURCE_DTL (TENANT_ID);






