BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE AB_BRIEF_STATUS';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE AB_BRIEF_STATUS (
    ID NUMBER(6,0) NOT NULL PRIMARY KEY,
    STATUS VARCHAR2(20) NULL,
    STATUSNAME VARCHAR2(100) NULL,
    BUS_TYPE VARCHAR2(20) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE AB_BRIEF_STATUS IS '票据流水业务状态表';
COMMENT ON COLUMN AB_BRIEF_STATUS.ID IS '序号';
COMMENT ON COLUMN AB_BRIEF_STATUS.STATUS IS '业务状态代码';
COMMENT ON COLUMN AB_BRIEF_STATUS.STATUSNAME IS '业务状态名称';
COMMENT ON COLUMN AB_BRIEF_STATUS.BUS_TYPE IS '业务类型代码';
COMMENT ON COLUMN AB_BRIEF_STATUS.TENANT_ID IS '租户ID';

CREATE INDEX IDX_AB_BRIEF_STATUS_TENANT_ID ON AB_BRIEF_STATUS (TENANT_ID);






