BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE BIS_BIF_INIT';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE BIS_BIF_INIT (
    ID VARCHAR2(32) NOT NULL,
    BIF_CODE VARCHAR2(4) NOT NULL,
    NAME VARCHAR2(30) NOT NULL,
    BANK_TYPE_ID VARCHAR2(32) NULL,
    VALID_SIGN VARCHAR2(1) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    IS_SYSTEM VARCHAR2(1) NULL,
    IS_DOMESTIC_BANK CHAR(1) DEFAULT '1' NULL,
    IS_SUPPORT_BANK_FOREIGN CHAR(1) DEFAULT '0' NULL,
    DIS_CONNECTION_ALERT VARCHAR2(10) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON COLUMN BIS_BIF_INIT.ID IS 'id';
COMMENT ON COLUMN BIS_BIF_INIT.BIF_CODE IS '接口代码';
COMMENT ON COLUMN BIS_BIF_INIT.NAME IS '接口代码名称';
COMMENT ON COLUMN BIS_BIF_INIT.BANK_TYPE_ID IS '银行类别编码';
COMMENT ON COLUMN BIS_BIF_INIT.VALID_SIGN IS '有效标志';
COMMENT ON COLUMN BIS_BIF_INIT.TENANT_ID IS '租户ID';






BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE BIS_BIF_RULE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE BIS_BIF_RULE (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    BIF_CODE CHAR(4) NOT NULL,
    BIF_NAME VARCHAR2(30) NOT NULL,
    PAYER_NAME NUMBER(6,0) NULL,
    PAYER_ACC NUMBER(6,0) NULL,
    PAYER_BANK NUMBER(6,0) NULL,
    PAYEE_NAME NUMBER(6,0) NULL,
    PAYEE_ACC NUMBER(6,0) NULL,
    PAYEE_BANK NUMBER(6,0) NULL,
    PURPOSE NUMBER(6,0) NULL,
    ADD_WORD NUMBER(6,0) NULL,
    IS_PURPOSE CHAR(1) NULL,
    IS_BANK_ONLINE VARCHAR2(1) NULL,
    SEND_NUM NUMBER(6,0) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    IS_ADD_BILLNO VARCHAR2(10) NULL,
    IS_MUST_BANK_CODE VARCHAR2(10) DEFAULT '0' NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE BIS_BIF_RULE IS '接口代码业务规则表';
COMMENT ON COLUMN BIS_BIF_RULE.BIF_CODE IS '接口代码';
COMMENT ON COLUMN BIS_BIF_RULE.BIF_NAME IS '接口代码名称';
COMMENT ON COLUMN BIS_BIF_RULE.PAYER_NAME IS '付款人';
COMMENT ON COLUMN BIS_BIF_RULE.PAYER_ACC IS '付款账号';
COMMENT ON COLUMN BIS_BIF_RULE.PAYER_BANK IS '付款开户行';
COMMENT ON COLUMN BIS_BIF_RULE.PAYEE_NAME IS '收款人';
COMMENT ON COLUMN BIS_BIF_RULE.PAYEE_ACC IS '收款账号';
COMMENT ON COLUMN BIS_BIF_RULE.PAYEE_BANK IS '收款开户行';
COMMENT ON COLUMN BIS_BIF_RULE.PURPOSE IS '用途';
COMMENT ON COLUMN BIS_BIF_RULE.ADD_WORD IS '附言';
COMMENT ON COLUMN BIS_BIF_RULE.IS_PURPOSE IS '用途是否支持特殊字符 1-是 0-否';
COMMENT ON COLUMN BIS_BIF_RULE.IS_BANK_ONLINE IS '银行代发是否在线';
COMMENT ON COLUMN BIS_BIF_RULE.SEND_NUM IS '银行代发发送数';
COMMENT ON COLUMN BIS_BIF_RULE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_BIS_BIF_RULE_TENANT_ID ON BIS_BIF_RULE (TENANT_ID);






