BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE BT_CURRENCY_INIT';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE BT_CURRENCY_INIT (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    CUR_NAME VARCHAR2(30) NULL,
    ENGLISH_CODE VARCHAR2(30) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE BT_CURRENCY_INIT IS '系统币别表';
COMMENT ON COLUMN BT_CURRENCY_INIT.TENANT_ID IS '租户ID';

CREATE INDEX IDX_BT_CURRENCY_INIT_TENANT_ID ON BT_CURRENCY_INIT (TENANT_ID);






BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE BT_PAY_TYPE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE BT_PAY_TYPE (
    ID VARCHAR2(32) NOT NULL,
    SYS_VOUCHER_CODE VARCHAR2(2) NOT NULL PRIMARY KEY,
    SYS_VOUCHER_NAME VARCHAR2(20) NOT NULL,
    RMK VARCHAR2(40) NULL,
    VALID_SIGN VARCHAR2(1) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE BT_PAY_TYPE IS '系统结算方式表';
COMMENT ON COLUMN BT_PAY_TYPE.ID IS 'id';
COMMENT ON COLUMN BT_PAY_TYPE.SYS_VOUCHER_CODE IS '结算方式编码';
COMMENT ON COLUMN BT_PAY_TYPE.SYS_VOUCHER_NAME IS '结算方式名称';
COMMENT ON COLUMN BT_PAY_TYPE.RMK IS '备注';
COMMENT ON COLUMN BT_PAY_TYPE.VALID_SIGN IS '有效标志';
COMMENT ON COLUMN BT_PAY_TYPE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_BT_PAY_TYPE_TENANT_ID ON BT_PAY_TYPE (TENANT_ID);






