CREATE TABLE CON_TYPE (
    id VARCHAR2(64) NOT NULL PRIMARY KEY,
    con_code VARCHAR2(10) NULL,
    con_name VARCHAR2(100) NULL,
    corp_id VARCHAR2(32) NULL,
    share_sign VARCHAR2(1) NULL,
    valid_sign VARCHAR2(1) NULL,
    rmk VARCHAR2(500) NULL,
    create_id VARCHAR2(32) NULL,
    create_time DATE NULL,
    update_id VARCHAR2(32) NULL,
    update_time DATE NULL,
    corp_name VARCHAR2(255) NULL,
    corp_code VARCHAR2(255) NULL,
    tenant_id VARCHAR2(32) NULL
);

COMMENT ON COLUMN CON_TYPE.corp_name IS '鍗曚綅鍚嶇О';
COMMENT ON COLUMN CON_TYPE.corp_code IS '鍗曚綅缂栫爜';

