EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE E_RECEIPT_TYPE (
    BILL_TYPE CHAR(2) NOT NULL PRIMARY KEY,
    BILL_NAME VARCHAR2(40) NOT NULL,
    TABLE_NAME VARCHAR2(40) NULL,
    VALID_SIGN VARCHAR2(1) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE E_RECEIPT_TYPE IS '电子回单类型表';
COMMENT ON COLUMN E_RECEIPT_TYPE.BILL_TYPE IS '类型编码';
COMMENT ON COLUMN E_RECEIPT_TYPE.BILL_NAME IS '类型名称';
COMMENT ON COLUMN E_RECEIPT_TYPE.TABLE_NAME IS '对应表名';
COMMENT ON COLUMN E_RECEIPT_TYPE.VALID_SIGN IS '有效标志 1-有效 0-无效';
COMMENT ON COLUMN E_RECEIPT_TYPE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_E_RECEIPT_TYPE_BT_VS ON E_RECEIPT_TYPE (BILL_TYPE, VALID_SIGN);
CREATE INDEX IDX_E_RECEIPT_TYPE_TENANT_ID ON E_RECEIPT_TYPE (TENANT_ID);






