BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE FC_MANUAL_FINACIAL_TYPE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE FC_MANUAL_FINACIAL_TYPE (
    SYS_RACE_CODE VARCHAR2(6) NOT NULL,
    NAME VARCHAR2(50) NULL,
    URL CLOB NULL,
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    FLOW_TYPE VARCHAR2(2) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE FC_MANUAL_FINACIAL_TYPE IS '手工帐类型表';
COMMENT ON COLUMN FC_MANUAL_FINACIAL_TYPE.SYS_RACE_CODE IS '系统业务种类';
COMMENT ON COLUMN FC_MANUAL_FINACIAL_TYPE.NAME IS '手工帐名称';
COMMENT ON COLUMN FC_MANUAL_FINACIAL_TYPE.URL IS '需要记手工帐的查询连接';
COMMENT ON COLUMN FC_MANUAL_FINACIAL_TYPE.FLOW_TYPE IS '流程类型1记账、2改账、3复核';
COMMENT ON COLUMN FC_MANUAL_FINACIAL_TYPE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_FC_MANUAL_FINACIAL_TYPE_T ON FC_MANUAL_FINACIAL_TYPE (TENANT_ID);






