BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE FC_SUBJECT_SORT';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE FC_SUBJECT_SORT (
    SYS_SUBJECT_CODE VARCHAR2(4) NOT NULL PRIMARY KEY,
    SYS_SUBJECT_NAME VARCHAR2(60) NOT NULL,
    IF_UNIQUE VARCHAR2(1) NULL,
    RMK VARCHAR2(40) NULL,
    ID VARCHAR2(32) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON COLUMN FC_SUBJECT_SORT.SYS_SUBJECT_CODE IS '系统科目代码';
COMMENT ON COLUMN FC_SUBJECT_SORT.SYS_SUBJECT_NAME IS '系统科目名称';
COMMENT ON COLUMN FC_SUBJECT_SORT.IF_UNIQUE IS '是否唯一';
COMMENT ON COLUMN FC_SUBJECT_SORT.RMK IS '备注';
COMMENT ON COLUMN FC_SUBJECT_SORT.TENANT_ID IS '租户ID';

CREATE INDEX IDX_FC_SUBJECT_SORT_TENANT_ID ON FC_SUBJECT_SORT (TENANT_ID);






