EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE FC_VOUCHER_ENTRY_INIT (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    BUSINESS_RULE_DEFINE_ID VARCHAR2(32) NOT NULL,
    BELONG_TYPE NUMBER(2,0) NULL,
    BALANCE_WAY NUMBER(1,0) NULL,
    SUBJECT_CODE VARCHAR2(32) NULL,
    ACCOUNT VARCHAR2(50) NULL,
    CUR_CODE VARCHAR2(32) NULL,
    SUMMARY VARCHAR2(32) NULL,
    ENTRY_TYPE NUMBER(2,0) NULL,
    GROUP_NUM NUMBER(2,0) NULL,
    VOUCHER_TYPE VARCHAR2(32) NULL,
    CREATE_TIME DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_TIME DATE NULL,
