BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE FEX_TRAN_INFO';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE FEX_TRAN_INFO (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    TRAN_CODE VARCHAR2(30) NULL,
    TRAN_NAME VARCHAR2(150) NULL,
    CREATE_BY VARCHAR2(32) NULL,
    CREATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE FEX_TRAN_INFO IS '交易编码表';
COMMENT ON COLUMN FEX_TRAN_INFO.TENANT_ID IS '租户ID';

CREATE INDEX IDX_FEX_TRAN_INFO_TENANT_ID ON FEX_TRAN_INFO (TENANT_ID);






