BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE NIS_BUSINESS_TYPE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE NIS_BUSINESS_TYPE (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    BUS_TYPE VARCHAR2(10) NOT NULL,
    BUS_TYPE_NAME VARCHAR2(30) NOT NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE NIS_BUSINESS_TYPE IS '费用报销-业务类型表';
COMMENT ON COLUMN NIS_BUSINESS_TYPE.ID IS 'id';
COMMENT ON COLUMN NIS_BUSINESS_TYPE.BUS_TYPE IS '业务类型编码';
COMMENT ON COLUMN NIS_BUSINESS_TYPE.BUS_TYPE_NAME IS '业务类型名称';
COMMENT ON COLUMN NIS_BUSINESS_TYPE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_NIS_BUSINESS_TYPE_BT_BTN ON NIS_BUSINESS_TYPE (BUS_TYPE, BUS_TYPE_NAME);
CREATE INDEX IDX_NIS_BUSINESS_TYPE_T ON NIS_BUSINESS_TYPE (TENANT_ID);






