CREATE TABLE NIS_OPERATION_TYPE (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    OP_TYPE VARCHAR2(10) NOT NULL,
    OP_TYPE_NAME VARCHAR2(30) NOT NULL,
    BUS_TYPE VARCHAR2(32) NOT NULL,
    TENANT_ID VARCHAR2(32) NULL
);

