COMMENT ON COLUMN NIS_OPERATION_TYPE.ID IS 'id';
COMMENT ON COLUMN NIS_OPERATION_TYPE.OP_TYPE IS '操作类型编码';
COMMENT ON COLUMN NIS_OPERATION_TYPE.OP_TYPE_NAME IS '操作类型名称';
COMMENT ON COLUMN NIS_OPERATION_TYPE.BUS_TYPE IS '业务类型';
COMMENT ON COLUMN NIS_OPERATION_TYPE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_NIS_OPERATION_TYPE_O_B_O ON NIS_OPERATION_TYPE (OP_TYPE, BUS_TYPE, OP_TYPE_NAME);
CREATE INDEX IDX_NIS_OPERATION_TYPE_T ON NIS_OPERATION_TYPE (TENANT_ID);






