BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE RAT_SYS_ITEM';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE RAT_SYS_ITEM (
    CODE VARCHAR2(20) NOT NULL PRIMARY KEY,
    NAME VARCHAR2(60) NOT NULL,
    "TYPE" NUMBER(6,0) NULL,
    RMK CLOB NULL,
    STATUS NUMBER(6,0) NULL,
    FLAG CHAR(1) NULL,
    ID VARCHAR2(32) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE RAT_SYS_ITEM IS '系统授信品种';
COMMENT ON COLUMN RAT_SYS_ITEM.CODE IS '系统授信品种代码';
COMMENT ON COLUMN RAT_SYS_ITEM.NAME IS '系统授信品种名称';
COMMENT ON COLUMN RAT_SYS_ITEM."TYPE" IS '授信类型';
COMMENT ON COLUMN RAT_SYS_ITEM.RMK IS '备注';
COMMENT ON COLUMN RAT_SYS_ITEM.STATUS IS '状态';
COMMENT ON COLUMN RAT_SYS_ITEM.FLAG IS '综合标识';
COMMENT ON COLUMN RAT_SYS_ITEM.TENANT_ID IS '租户ID';

CREATE INDEX IDX_RAT_SYS_ITEM_TENANT_ID ON RAT_SYS_ITEM (TENANT_ID);






