BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE SYS_CELL_MANAGE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE SYS_CELL_MANAGE (
    id VARCHAR2(32) NOT NULL PRIMARY KEY,
    cell_code VARCHAR2(20) NOT NULL,
    cell_name VARCHAR2(200) NOT NULL,
    parent_id VARCHAR2(32) NULL,
    rmk VARCHAR2(500) NULL,
    valid_sign VARCHAR2(2) NULL,
    create_id VARCHAR2(32) NULL,
    create_time DATE NULL,
    update_id VARCHAR2(32) NULL,
    update_time DATE NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON COLUMN SYS_CELL_MANAGE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_SYS_CELL_MANAGE_TENANT_ID ON SYS_CELL_MANAGE (TENANT_ID);






