BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE SYS_COUNTRY';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE SYS_COUNTRY (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    CODE VARCHAR2(30) NULL,
    NAME_ZH VARCHAR2(100) NULL,
    NAME_EN VARCHAR2(200) NULL,
    IS_SYSTEM VARCHAR2(1) DEFAULT '0' NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    continent VARCHAR2(32) NULL,
    TENANT_ID VARCHAR2(32) NULL,
    ISO_TWO VARCHAR2(32) NULL,
    ISO_THREE VARCHAR2(32) NULL
);

COMMENT ON TABLE SYS_COUNTRY IS '国家表';
COMMENT ON COLUMN SYS_COUNTRY.NAME_ZH IS '中文名称';
COMMENT ON COLUMN SYS_COUNTRY.NAME_EN IS '英文名称';
COMMENT ON COLUMN SYS_COUNTRY.IS_SYSTEM IS '系统初始化标志  1-是 0-否';
COMMENT ON COLUMN SYS_COUNTRY.CREATE_DATE IS '创建时间';
COMMENT ON COLUMN SYS_COUNTRY.CREATE_BY IS '创建人';
COMMENT ON COLUMN SYS_COUNTRY.UPDATE_DATE IS '更新时间';
COMMENT ON COLUMN SYS_COUNTRY.UPDATE_BY IS '更新人';
COMMENT ON COLUMN SYS_COUNTRY.TENANT_ID IS '租户ID';

CREATE INDEX IDX_SYS_COUNTRY_TENANT_ID ON SYS_COUNTRY (TENANT_ID);






BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE SYS_DICT';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE SYS_DICT (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    TYPE_CODE VARCHAR2(50) NULL,
    TYPE_NAME VARCHAR2(100) NULL,
    TYPE_ID VARCHAR2(32) NULL,
    TYPE_GROUP_ID VARCHAR2(32) NULL,
    SORT NUMBER(6,0) NULL,
    CREATE_DATE DATE NULL,
    CREATE_NAME VARCHAR2(50) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE SYS_DICT IS '平台字典';
COMMENT ON COLUMN SYS_DICT.SORT IS '排序';
COMMENT ON COLUMN SYS_DICT.TENANT_ID IS '租户ID';

CREATE INDEX IDX_TYPE_GROUP_ID ON SYS_DICT (TYPE_GROUP_ID);
CREATE INDEX IDX_SYS_DICT_TENANT_ID ON SYS_DICT (TENANT_ID);






