BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE SYS_DICT_GROUP';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE SYS_DICT_GROUP (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    TYPE_GROUP_CODE VARCHAR2(50) NULL,
    TYPE_GROUP_NAME VARCHAR2(50) NULL,
    CREATE_DATE DATE NULL,
    CREATE_NAME VARCHAR2(50) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE SYS_DICT_GROUP IS '平台字典组';
COMMENT ON COLUMN SYS_DICT_GROUP.TENANT_ID IS '租户ID';

CREATE INDEX IDX_GROUP_CODE ON SYS_DICT_GROUP (TYPE_GROUP_CODE);
CREATE INDEX IDX_SYS_DICT_GROUP_TENANT_ID ON SYS_DICT_GROUP (TENANT_ID);






