CREATE TABLE SYS_INTERNATION (
    KEY_ID VARCHAR2(50) NOT NULL,
    LANG_CODE VARCHAR2(20) NOT NULL,
    LANG_CONTEXT VARCHAR2(1000) NULL,
    TENANT_ID VARCHAR2(32) NULL,
    CONSTRAINT PK_SYS_INTERNATION PRIMARY KEY (KEY_ID, LANG_CODE)
);

COMMENT ON COLUMN SYS_INTERNATION.TENANT_ID IS '租户ID';

CREATE INDEX IDX_SYS_INTERNATION_TENANT_ID ON SYS_INTERNATION (TENANT_ID);






