BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE SYS_MULTI_LANG';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE SYS_MULTI_LANG (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    LANG_CODE VARCHAR2(50) NULL,
    LANG_CONTEXT CLOB NULL,
    LANG_KEY VARCHAR2(60) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    CREATE_NAME VARCHAR2(50) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    UPDATE_NAME VARCHAR2(50) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON COLUMN SYS_MULTI_LANG.ID IS '主键';
COMMENT ON COLUMN SYS_MULTI_LANG.LANG_CODE IS '语言';
COMMENT ON COLUMN SYS_MULTI_LANG.LANG_CONTEXT IS '内容';
COMMENT ON COLUMN SYS_MULTI_LANG.LANG_KEY IS '语言主键';
COMMENT ON COLUMN SYS_MULTI_LANG.TENANT_ID IS '租户ID';

CREATE INDEX IDX_SYS_MULTI_LANG ON SYS_MULTI_LANG (LANG_KEY, LANG_CODE);
CREATE INDEX IDX_SYS_MULTI_LANG_TENANT_ID ON SYS_MULTI_LANG (TENANT_ID);






