BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE SYS_PROVINCE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE SYS_PROVINCE (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    PROVINCE_CODE VARCHAR2(64) NULL,
    PROVINCE_NAME VARCHAR2(128) NULL,
    STATUS VARCHAR2(2) DEFAULT '1' NOT NULL,
    CREATE_TIME DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_TIME DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE SYS_PROVINCE IS '省区维护';
COMMENT ON COLUMN SYS_PROVINCE.ID IS '主键';
COMMENT ON COLUMN SYS_PROVINCE.PROVINCE_CODE IS '省区编码';
COMMENT ON COLUMN SYS_PROVINCE.PROVINCE_NAME IS '省区名称';
COMMENT ON COLUMN SYS_PROVINCE.STATUS IS '状态:1-启用;0-禁用';
COMMENT ON COLUMN SYS_PROVINCE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_SYS_PROVINCE_TENANT_ID ON SYS_PROVINCE (TENANT_ID);






