CREATE TABLE TP_BILL_VIEW (
    id VARCHAR2(32) NOT NULL PRIMARY KEY,
    pay_type VARCHAR2(20) NULL,
    table_code VARCHAR2(20) NULL,
    show_name VARCHAR2(20) NULL,
